CREATE FUNCTION public.can_link_appointment_contact(_tenant uuid,_appointment uuid,_contact uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(EXISTS(SELECT 1 FROM public.project_appointments a JOIN public.client_contacts c ON c.tenant_id=a.tenant_id AND c.id=_contact AND c.client_id IN(a.contracting_client_id,a.invoicing_client_id) AND c.active WHERE a.id=_appointment AND a.tenant_id=_tenant AND public.can_manage_project(a.tenant_id,a.project_id)),false) $$;
REVOKE ALL ON FUNCTION public.can_link_appointment_contact(uuid,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_link_appointment_contact(uuid,uuid,uuid) TO authenticated,service_role;
ALTER POLICY appointed_contacts_insert ON public.appointment_contacts WITH CHECK(public.can_link_appointment_contact(tenant_id,appointment_id,contact_id));
CREATE FUNCTION public.guard_appointment_commercial_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME='appointment_commercials' AND NEW.appointment_id<>OLD.appointment_id THEN RAISE EXCEPTION 'APPOINTMENT_IMMUTABLE';END IF; RETURN NEW; END $$;
CREATE TRIGGER appointment_money_identity BEFORE UPDATE ON public.appointment_commercials FOR EACH ROW EXECUTE FUNCTION public.guard_appointment_commercial_identity();
CREATE FUNCTION public.guard_client_default_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.client_id<>OLD.client_id THEN RAISE EXCEPTION 'CLIENT_DEFAULT_IMMUTABLE';END IF;RETURN NEW;END $$;
CREATE TRIGGER default_client_identity BEFORE UPDATE ON public.client_commercial_defaults FOR EACH ROW EXECUTE FUNCTION public.guard_client_default_identity();